import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Typography,
} from '@mui/material';
import { useAuth } from '../context/AuthContext';
import { dashboardService } from '../services/dashboardService';
import { hierarchyService } from '../services/hierarchyService';
import { DashboardSkeleton } from '../components/common/SkeletonLoader';
import EmptyState from '../components/common/EmptyState';
import { useDemoMode } from '../hooks/useDemoMode';
import SummaryCards from '../components/dashboard/SummaryCards';
import SurveyProgress from '../components/dashboard/SurveyProgress';
import RecentActivity from '../components/dashboard/RecentActivity';
import PropertyStats from '../components/dashboard/PropertyStats';

const Dashboard = () => {
  const { user, hasAnyRole } = useAuth();
  const { getFallbackData, isDemoMode } = useDemoMode();
  const [dashboardData, setDashboardData] = useState(null);
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [usingFallback, setUsingFallback] = useState(false);

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);
      setUsingFallback(false);

      const organizationId = user?.organizationId;

      // Load dashboard stats and properties in parallel
      const [dashboardResult, propertiesResult] = await Promise.all([
        dashboardService.getAllDashboardData(organizationId),
        hierarchyService.getProperties(organizationId),
      ]);

      setDashboardData(dashboardResult);
      setProperties(propertiesResult);
    } catch (err) {
      console.error('Failed to load dashboard data:', err);

      // Use demo data as fallback if available
      if (isDemoMode) {
        const fallbackDashboardData = getFallbackData('dashboardStats');
        const fallbackProperties = getFallbackData('properties');

        if (fallbackDashboardData || fallbackProperties) {
          setDashboardData({ stats: fallbackDashboardData });
          setProperties(fallbackProperties || []);
          setUsingFallback(true);
          setError(null);
          return;
        }
      }

      setError(err.message || 'Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  const handleRetry = () => {
    loadDashboardData();
  };

  if (loading) {
    return (
      <Box m={3}>
        <Typography variant="h4" gutterBottom>
          Dashboard
        </Typography>
        <DashboardSkeleton />
      </Box>
    );
  }

  if (error && !usingFallback) {
    return (
      <Box m={3}>
        <Typography variant="h4" gutterBottom>
          Dashboard
        </Typography>
        <EmptyState
          type="search"
          title="Failed to Load Dashboard"
          description="We couldn't load your dashboard data. Please check your connection and try again."
          action={{
            label: 'Retry',
            onClick: handleRetry,
          }}
        />
      </Box>
    );
  }

  const hasData = dashboardData?.stats || properties?.length > 0;

  if (!hasData) {
    return (
      <Box m={3}>
        <Typography variant="h4" gutterBottom>
          Dashboard
        </Typography>
        <EmptyState
          type="properties"
          title="Welcome to Site Survey Tool"
          description="Get started by creating your first property to begin managing site surveys."
          action={{
            label: 'Create Property',
            onClick: () => window.location.href = '/settings',
          }}
        />
      </Box>
    );
  }

  return (
    <Box m={3}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h4">
          Dashboard
        </Typography>
        {usingFallback && (
          <Typography variant="caption" color="warning.main" sx={{ fontWeight: 'bold' }}>
            🎭 Using Demo Data
          </Typography>
        )}
      </Box>

      <Grid container spacing={3}>
        {/* Summary Cards */}
        <Grid item xs={12}>
          <SummaryCards 
            stats={dashboardData?.stats} 
            userRole={user?.role}
          />
        </Grid>

        {/* Survey Progress */}
        <Grid item xs={12} md={6}>
          <SurveyProgress 
            surveyStatuses={dashboardData?.surveyStatuses}
            userRole={user?.role}
          />
        </Grid>

        {/* Property Statistics */}
        <Grid item xs={12} md={6}>
          <PropertyStats 
            propertyStats={dashboardData?.propertyStats}
            properties={properties}
            userRole={user?.role}
          />
        </Grid>

        {/* Recent Activity - Only for admins */}
        {hasAnyRole(['ROLE_SUPER_ADMIN', 'ROLE_ORG_ADMIN']) && (
          <Grid item xs={12}>
            <RecentActivity 
              userActivity={dashboardData?.userActivity}
            />
          </Grid>
        )}
      </Grid>
    </Box>
  );
};

export default Dashboard;
